+    });
+    item.addEventListener("mouseleave", () => {
+      if (isSmall()) return;
+      closeAll(null);
+    });
+
+    // Click (all)
+    btn.addEventListener("click", (e) => {
+      e.preventDefault();
+      const expanded = btn.getAttribute("aria-expanded") === "true";
+      if (expanded) closeAll(null);
+      else openMenu(id);
+    });
+  }
